<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { api, currency } from '../services/api'
import { useCartStore } from '../stores/cart'
import type { Address } from '../types'
const cart=useCartStore();const router=useRouter();const addresses=ref<Address[]>([]);const addressId=ref('');const shipping=ref('regular');const coupon=ref('');const quote=ref<{subtotal:number;discount_amount:number;shipping_fee:number;total:number;coupon_code?:string}|null>(null);const loading=ref(true);const busy=ref(false);const error=ref('')
const canSubmit=computed(()=>Boolean(addressId.value&&cart.cart?.items.length&&!busy.value))
async function updateQuote(){if(!addressId.value||!cart.cart?.items.length){quote.value=null;return}try{quote.value=await api.post('/api/v1/checkout/quote',{address_id:addressId.value,shipping_method:shipping.value,coupon_code:coupon.value||null})}catch(e){quote.value=null;error.value=e instanceof Error?e.message:'Tidak bisa menghitung total'}}
onMounted(async()=>{try{await Promise.all([cart.fetch(),api.get<Address[]>('/api/v1/addresses').then(a=>{addresses.value=a;addressId.value=a.find(x=>x.is_default)?.id??a[0]?.id??''})]);await updateQuote()}catch(e){error.value=e instanceof Error?e.message:'Gagal menyiapkan checkout'}finally{loading.value=false}})
watch([addressId,shipping],updateQuote)
async function submit(){if(!canSubmit.value)return;busy.value=true;error.value='';try{const order=await api.post<{id:string}>('/api/v1/orders',{address_id:addressId.value,shipping_method:shipping.value,coupon_code:coupon.value||null},{'Idempotency-Key':crypto.randomUUID()});router.push({name:'orders',query:{new:order.id}})}catch(e){error.value=e instanceof Error?e.message:'Gagal membuat pesanan'}finally{busy.value=false}}
</script>
<template><section class="page-intro"><p class="eyebrow">LANGKAH TERAKHIR</p><h1>Checkout</h1><p>Pastikan alamat dan rincian pesanan sudah benar.</p></section><div v-if="loading" class="loading-state"><span class="spinner"></span>Menyiapkan checkout…</div><div v-else-if="!cart.cart?.items.length" class="empty-state"><h3>Keranjang kosong</h3><p>Tambahkan produk terlebih dahulu.</p><RouterLink to="/products" class="button-primary">Lihat produk</RouterLink></div><div v-else class="checkout-layout"><form class="checkout-form" @submit.prevent="submit"><section class="checkout-section"><div class="section-heading"><div><p class="eyebrow">01 / PENGIRIMAN</p><h2>Alamat pengiriman</h2></div><RouterLink to="/profile" class="text-link">Kelola alamat</RouterLink></div><label v-if="addresses.length" class="field-label">Pilih alamat<select v-model="addressId" required><option v-for="a in addresses" :key="a.id" :value="a.id">{{ a.label }} · {{ a.recipient_name }} — {{ a.city }}</option></select></label><div v-if="addressId&&addresses.find(a=>a.id===addressId)" class="address-preview"><strong>{{ addresses.find(a=>a.id===addressId)?.recipient_name }} · {{ addresses.find(a=>a.id===addressId)?.phone }}</strong><p>{{ addresses.find(a=>a.id===addressId)?.address_line }}, {{ addresses.find(a=>a.id===addressId)?.city }}, {{ addresses.find(a=>a.id===addressId)?.province }} {{ addresses.find(a=>a.id===addressId)?.postal_code }}</p></div><div v-if="!addresses.length" class="empty-address"><p>Kamu belum memiliki alamat tersimpan.</p><RouterLink to="/profile" class="button-secondary">Tambahkan alamat dahulu</RouterLink></div></section><section class="checkout-section"><p class="eyebrow">02 / PENGIRIMAN</p><h2>Metode pengiriman</h2><label class="choice-card"><input v-model="shipping" type="radio" value="regular"/><span><strong>Reguler</strong><small>Estimasi 2–5 hari kerja</small></span><strong>{{ Number(cart.subtotal)>=200000?'Gratis':currency(15000) }}</strong></label><label class="choice-card"><input v-model="shipping" type="radio" value="express"/><span><strong>Express</strong><small>Estimasi 1–2 hari kerja</small></span><strong>{{ currency(30000) }}</strong></label></section><section class="checkout-section"><p class="eyebrow">03 / PROMO</p><h2>Kode promo</h2><div class="coupon-row"><input v-model="coupon" placeholder="Contoh: HEMAT10"/><button type="button" class="button-secondary" @click="updateQuote">Terapkan</button></div><small class="muted">Kode demo: HEMAT10 · Diskon 10% jika memenuhi ketentuan.</small></section><p v-if="error" class="error-banner">{{ error }}</p><button class="button-primary full-button" :disabled="!canSubmit||!addresses.length">{{ busy?'Membuat pesanan…':'Buat pesanan' }}</button><p class="muted small">Pembayaran menggunakan mode simulasi di project demo. Tidak ada uang sungguhan yang ditagihkan.</p></form><aside class="summary-card"><h2>Pesananmu</h2><div v-for="item in cart.cart?.items" :key="item.id" class="mini-order-item"><img :src="item.product.image_url" :alt="item.product.name"/><div><strong>{{ item.product.name }}</strong><small>{{ item.quantity }} × {{ currency(item.price) }}</small></div><strong>{{ currency(item.line_total) }}</strong></div><div class="summary-line"><span>Subtotal</span><strong>{{ currency(quote?.subtotal??cart.subtotal) }}</strong></div><div class="summary-line"><span>Diskon</span><strong class="discount-text">−{{ currency(quote?.discount_amount??0) }}</strong></div><div class="summary-line"><span>Ongkir</span><strong>{{ quote?currency(quote.shipping_fee):'—' }}</strong></div><div class="summary-total"><span>Total</span><strong>{{ quote?currency(quote.total):'Hitung total' }}</strong></div><button class="button-secondary full-button" type="button" @click="updateQuote">Hitung ulang total</button></aside></div></template>
